def solve(g):
    h,w=len(g),len(g[0]); vals=set(x for r in g for x in r)
    wall=list(vals-{0})[0] if 0 in vals else None
    # find enclosed background regions (background = 0); walls = non-zero
    seen=set();enc=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and (i,j) not in seen:
                q=[(i,j)];reg=[];touches=True
                while q:
                    x,y=q.pop()
                    if x==0 or x==h-1 or y==0 or y==w-1: touches=False
                    if(x,y)in seen: continue
                    seen.add((x,y));reg.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<h and 0<=b<w and g[a][b]==0 and(a,b)not in seen: q.append((a,b))
                enc.append((reg,touches))
    print("enclosed bg regions:",[(len(r),min(p[0] for p in r),max(p[0] for p in r),min(p[1] for p in r),max(p[1] for p in r)) for r,_ in enc if not _])
    return enc

